{% from "partials/button.html" import ui_button, ui_link %}
{% from "partials/switch.html" import ui_switch %}
{% from "partials/gallery-bar.html" import gallery_bar %}

{% call gallery_bar('Edit user' if member else 'Add user', '' if member else 'The user will choose their password after opening a one-time invitation link.', 'detail-heading') %}
  {{ ui_link('← Back to users', '/admin/members', size='small', class_name='detail-back') }}
{% endcall %}
{% if member %}<div class="detail-person"><span class="member-avatar" aria-hidden="true">{{ member.username[:2] | upper }}</span><span><strong>{{ member.username }}</strong><small>{{ member.contact_email }}</small></span></div>{% endif %}

{% if allowed_actions.allows('accounts.membership.manage') %}{{ ui_switch('Current library access', 'current_library_access', checked=member.is_bootstrap_owner or member.membership_role, disabled=member.is_bootstrap_owner, description='Allow this user to access ' ~ roster.library_name ~ '.', class_name='detail-setting') }}{% if member.is_bootstrap_owner %}<input type="hidden" name="current_library_access" value="on">{% endif %}{% endif %}
{% if member.membership_role and member.has_credential and allowed_actions.allows('accounts.password_reset.send') %}<div class="detail-setting"><span><strong>Send password reset email</strong><small>Email a link to reset the user's password.</small></span>{{ ui_button('Send email', attributes={'data-admin-action': 'reset'}) }}</div>{% endif %}
{% if member.is_bootstrap_owner and allowed_actions.allows('accounts.welcome.send') %}<div class="detail-setting"><span><strong>Resend welcome email</strong><small>Email the username and sign-in URL, never a password.</small></span>{{ ui_button('Resend email', attributes={'data-admin-action': 'welcome'}) }}</div>{% endif %}
{% if allowed_actions.allows('accounts.sessions.revoke') %}<div class="detail-setting"><span><strong>Revoke all sessions</strong><small>Sign the user out from all active sessions.</small></span>{{ ui_button('Revoke sessions', attributes={'data-admin-action': 'revoke'}) }}</div>{% endif %}
{% if allowed_actions.allows('accounts.manage') and not member.is_bootstrap_owner %}<div class="detail-setting is-danger"><span><strong>{{ "Disable" if member.is_active else "Enable" }} account</strong><small>{{ "Prevent the user from signing in." if member.is_active else "Allow the user to sign in with their existing password." }}</small></span>{{ ui_button(('Disable' if member.is_active else 'Enable') ~ ' account', class_name='action-button--destructive', attributes={'data-admin-action': 'toggle-active'}) }}</div>{% endif %}

{% call gallery_bar('Users & access', 'Manage who can sign in and what they can do in ' ~ roster.library_name ~ '.', 'members-heading') %}
  {% if allowed_actions.allows('accounts.create') %}{{ ui_link('Add user', '/admin/accounts/new', variant='primary') }}{% endif %}
{% endcall %}

{% from "components/on-page-alert.html" import on_page_alert %}
{% from "partials/switch.html" import ui_switch %}
{% from "partials/button.html" import ui_button %}

{% macro ui_link(label, href, variant='secondary', size='medium', class_name='', attributes={}) -%}
<a href="{{ href }}" class="button ui-button ui-button--{{ variant }} ui-button--{{ size }}{% if class_name %} {{ class_name }}{% endif %}"{% for key, item in attributes.items() %}{% if item is sameas true %} {{ key }}{% elif item is not sameas false and item is not none %} {{ key }}="{{ item | forceescape }}"{% endif %}{% endfor %}><span class="ui-button__content">{{ label }}</span></a>
{%- endmacro %}

{% endif %}
{% if not capability_ui.allowed_actions.get('library.media.read', false) %}
/* The player and its reserved lane disappear together, including restored compact modes. */
:root { --player-height: 0px !important; }
@media (min-width: 901px) {
  :root #shell-navigation-rail { height: 100% !important; padding-bottom: 20px; }
}
